from math import comb, log
from typing import Sequence


def is_div_covering(n: int, S: Sequence[int], T: Sequence[int]) -> bool:
    """Every i in [1, n] divides some s - t."""
    return all(any((s - t) % i == 0 for s in S for t in T) for i in range(1, n + 1))


def wall_check(n: int, S: Sequence[int], T: Sequence[int]) -> dict:
    """Verify a disjoint covering of [2n'] (n' = n // 2) against 4^n' <= (2n'+1) M^{|S||T|}."""
    if set(S) & set(T):
        raise ValueError("S and T must be disjoint (otherwise 0 = s - s covers everything)")
    if min(list(S) + list(T)) < 0:
        raise ValueError("entries must lie in [0, M]")
    m = n // 2
    M = max(list(S) + list(T))
    X = 1
    for s in S:
        for t in T:
            X *= abs(s - t)
    return {
        "covers": is_div_covering(2 * m, S, T),
        "central_binomial_divides_product": X % comb(2 * m, m) == 0,
        "log_lhs": m * log(4),
        "log_rhs": log(2 * m + 1) + len(S) * len(T) * log(M),
        "wall_holds": 4 ** m <= (2 * m + 1) * M ** (len(S) * len(T)),
    }


if __name__ == "__main__":
    k = 6
    S, T = [k * k + k * j for j in range(k)], list(range(k))
    print(wall_check(k * k, S, T))

from fractions import Fraction as Q


def three_leg_optimum(gamma: Q, u: Q, w: Q, c: Q) -> tuple[Q, tuple[Q, Q], tuple[Q, Q, Q]]:
    """Minimise max(a, c b, gamma - u a - w b).  Returns (value, optimiser, dual weights)."""
    if u < 0 or w < 0 or c <= 0:
        raise ValueError("need u, w >= 0 and c > 0")
    v = gamma / (1 + u + w / c)
    weights = (u, w / c, Q(1))           # u*a + (w/c)*(c b) + 1*(gamma - u a - w b) = gamma
    return v, (v, v / c), weights


def legs(gamma: Q, u: Q, w: Q, c: Q, a: Q, b: Q) -> tuple[Q, Q, Q]:
    return a, c * b, gamma - u * a - w * b


if __name__ == "__main__":
    half = Q(1, 2)
    for w, c in [(Q(1), Q(1)), (Q(3, 2), Q(1)), (Q(1, 2), Q(1))]:
        v, (a, b), wts = three_leg_optimum(half, half, w, c)
        print(f"w/c={w/c}: optimum {v} at ({a},{b}); legs {legs(half, half, w, c, a, b)}; dual weights {wts}")

from itertools import combinations


def is_div_covering(n: int, S: tuple[int, ...], T: tuple[int, ...]) -> bool:
    return all(any((s - t) % i == 0 for s in S for t in T) for i in range(1, n + 1))


def min_box(k: int, n: int, limit: int = 80) -> tuple[int, tuple[int, ...], tuple[int, ...]] | None:
    """Least M with disjoint k-subsets S, T of [0, M] covering [n] (exhaustive search, tiny k only)."""
    for M in range(max(n, 2 * k - 1), limit):       # trivial lower bound max(n, 2k-1)
        pts = range(M + 1)
        for S in combinations(pts, k):
            rest = [x for x in pts if x not in S]
            for T in combinations(rest, k):
                if (M in S or M in T) and is_div_covering(n, S, T):
                    return M, S, T
    return None


if __name__ == "__main__":
    for k in (1, 2):
        for n in range(1, k * k + 2 * k + 3):
            print(k, n, min_box(k, n))
